style.css:
/* 1. 모든 컨테이너의 폭 제한 해제 */
div, main, section, article {
    max-width: 100% !important;
}

/* 2. 표(Table) 가로폭 강제 확장 및 짤림 방지 */
table {
    width: 100% !important;
    display: table !important;
    table-layout: auto !important; /* 고정 폭 해제 */
    word-break: keep-all !important; /* 단어 단위 줄바꿈 방지 */
    white-space: normal !important;
}

/* 3. 표가 들어있는 칸의 여백 최소화 */
td, th {
    padding: 8px 12px !important;
    min-width: 150px !important; /* 칸이 너무 좁아지지 않게 */
}
